 static Material deskWood,deskBlack,deskGold,deskDarkGold,deskIvory,deskRubber,deskGlass;
 static void PrepareConsoleMaterials(){
  deskWood=Mat("Console oiled walnut",C("91613D"),0,.32f);deskBlack=Mat("Console black lacquer",C("182027"),.18f,.34f);
  deskGold=Mat("Console brushed champagne brass",C("C89E59"),.78f,.42f);deskDarkGold=Mat("Console recessed bronze",C("664B26"),.72f,.30f);
  deskIvory=Mat("Console warm porcelain",C("EFE6C9"),0,.25f);deskRubber=Mat("Console rubber and ebonite",C("101419"),.08f,.30f);
  int w=1024;var tex=new Texture2D(w,w,TextureFormat.RGB24,false);var colors=new Color[w*w];
  for(int y=0;y<w;y++)for(int x=0;x<w;x++){float bend=20*Mathf.PerlinNoise(x*.002f,y*.003f);float grain=Mathf.PerlinNoise(x*.005f,(y+bend)*.13f),fine=Mathf.PerlinNoise(x*.012f,(y+bend)*.55f);float band=Mathf.Sin((y+bend)*.16f+Mathf.PerlinNoise(x*.004f,y*.009f)*5);float v=.66f+.23f*grain+.07f*fine+.025f*band;colors[y*w+x]=new Color(v,v,v);}
  tex.SetPixels(colors);tex.Apply();string path=A+"Textures/ConsoleWalnut.png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);deskWood.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));deskWood.SetTextureScale("_BaseMap",new Vector2(.4f,.8f));EditorUtility.SetDirty(deskWood);
  deskGlass=Mat("Instrument clear glazing",new Color(.88f,.95f,1,.055f),0,.88f);deskGlass.SetFloat("_Surface",1);deskGlass.SetFloat("_ZWrite",0);deskGlass.SetFloat("_SrcBlend",5);deskGlass.SetFloat("_DstBlend",10);deskGlass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");deskGlass.SetShaderPassEnabled("ShadowCaster",false);deskGlass.renderQueue=3000;
 }
 // A rounded outline with a separately controlled corner radius and edge bevel.
 // Thin panel corner radii must not collapse to half the plate thickness.
 static Vector2[] RoundedLoop(float width,float depth,float radius,int steps=12){
  var points=new List<Vector2>();for(int corner=0;corner<4;corner++){float a0=corner*90;float cx=corner==0||corner==3?width/2-radius:-width/2+radius;float cy=corner<2?depth/2-radius:-depth/2+radius;for(int i=0;i<=steps;i++){float a=(a0+i*90f/steps)*Mathf.Deg2Rad;points.Add(new Vector2(cx+radius*Mathf.Cos(a),cy+radius*Mathf.Sin(a)));}}return points.ToArray();
 }
 static GameObject ProfileSolid(string name,Transform p,Vector3 at,Vector2[] outline,float thickness,Material mat,float bevel=.012f){
  // Outline is in x/z; extrusion is local y. The fan is valid for the convex panel outlines used here.
  var v=new List<Vector3>();var n=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();float b=Mathf.Min(bevel,thickness*.45f);Vector2 centre=outline.Aggregate(Vector2.zero,(a,c)=>a+c)/outline.Length;
  Action<Vector3,Vector3,Vector3,Vector3> tri=(a,c,d,normal)=>{int k=v.Count;if(Vector3.Dot(Vector3.Cross(c-a,d-a),normal)<0){var swap=c;c=d;d=swap;}v.Add(a);v.Add(c);v.Add(d);for(int j=0;j<3;j++)n.Add(normal);uv.Add(new Vector2(a.x,a.z));uv.Add(new Vector2(c.x,c.z));uv.Add(new Vector2(d.x,d.z));t.AddRange(new[]{k,k+1,k+2});};
  int count=outline.Length;var rings=new Vector3[4][];for(int ring=0;ring<4;ring++){rings[ring]=new Vector3[count];for(int i=0;i<count;i++){var a=outline[i];var incoming=(a-outline[(i+count-1)%count]).normalized;var outgoing=(outline[(i+1)%count]-a).normalized;var tangent=(incoming+outgoing).normalized;var outward=new Vector2(tangent.y,-tangent.x);float inset=ring==0||ring==3?b:0;float y=ring==0?-thickness/2:ring==1?-thickness/2+b:ring==2?thickness/2-b:thickness/2;rings[ring][i]=V(a.x-outward.x*inset,y,a.y-outward.y*inset);}}
  for(int i=0;i<count;i++){int j=(i+1)%count;tri(V(centre.x,thickness/2,centre.y),rings[3][i],rings[3][j],Vector3.up);tri(V(centre.x,-thickness/2,centre.y),rings[0][i],rings[0][j],Vector3.down);for(int r=0;r<3;r++){var a=rings[r][i];var c=rings[r][j];var d=rings[r+1][j];var normal=Vector3.Cross(c-a,d-a).normalized;var radial=V((a.x+c.x)/2-centre.x,0,(a.z+c.z)/2-centre.y);if(Vector3.Dot(normal,radial)<0)normal=-normal;tri(a,c,d,normal);tri(a,d,rings[r+1][i],normal);}}
  var mesh=new Mesh();mesh.SetVertices(v);mesh.SetNormals(n);mesh.SetUVs(0,uv);mesh.SetTriangles(t,0);return MeshObject(name,p,SaveMesh(mesh,"PrecisionPanel_"+meshSerial++),mat,at);
 }
 static GameObject PrecisionPanel(string name,Transform p,Vector3 at,Vector3 size,float corners,Material mat,float bevel=.008f)=>ProfileSolid(name,p,at,RoundedLoop(size.x,size.z,corners),size.y,mat,bevel);
 static void InstrumentScrew(Transform p,Vector3 at,Vector3 normal,float radius=.028f){var g=Group("Countersunk slotted screw",p,at);g.localRotation=Quaternion.FromToRotation(Vector3.up,normal);Lathe("Turned screw head",g,Vector3.zero,new[]{new Vector2(0,-.008f),new Vector2(radius*.74f,-.008f),new Vector2(radius,.002f),new Vector2(radius*.94f,.008f),new Vector2(0,.009f)},deskGold,24);Box("Recessed screwdriver slot",g,V(0,.010f,0),V(radius*1.25f,.002f,radius*.16f),deskRubber,.001f);}
 static void ConsolePlaque(Transform p,string text,Vector3 at,float width,float fontSize=.65f){PrecisionPanel("Machined engraved plaque",p,at,V(width,.018f,.18f),.018f,deskGold,.004f);FlatLabel(p,text,at+Vector3.up*.011f,fontSize,C("201A13"));}
 static Transform ConsoleCabinet(Transform stage){
  var root=Group("A · Precision mechanical console",stage,V(-6.25f,-.47f,3.55f));float width=4.80f,depth=3.45f,slope=14,centre=.57f;
  // The curved cabinet wall has one continuous slope; the metal insert is seated in its rebate.
  var outline=RoundedLoop(width,depth,.18f,16);var v=new List<Vector3>();var tris=new List<int>();var uv=new List<Vector2>();
  for(int i=0;i<outline.Length;i++){var q=outline[i];v.Add(V(q.x,.07f,q.y));v.Add(V(q.x,centre-Mathf.Tan(slope*Mathf.Deg2Rad)*q.y,q.y));uv.Add(new Vector2(q.x,q.y));uv.Add(new Vector2(q.x,q.y+.4f));int j=(i+1)%outline.Length;tris.AddRange(new[]{i*2,i*2+1,j*2,j*2,i*2+1,j*2+1});}
  var mesh=new Mesh();mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();MeshObject("Continuous rounded walnut cabinet",root,SaveMesh(mesh,"ConsoleCabinet"),deskWood);
  PrecisionPanel("Walnut lower moulding",root,V(0,.09f,0),V(width,.085f,depth),.18f,deskWood,.018f);
  for(int sx=-1;sx<=1;sx+=2)for(int sz=-1;sz<=1;sz+=2){Lathe("Compression rubber foot",root,V(sx*2.07f,0,sz*1.36f),new[]{new Vector2(0,0),new Vector2(.13f,0),new Vector2(.15f,.02f),new Vector2(.15f,.07f),new Vector2(.12f,.10f),new Vector2(0,.10f)},deskRubber,40);}
  var panel=Group("Reference sloping console face",root,V(0,centre,0));panel.localRotation=Quaternion.Euler(slope,0,0);
  PrecisionPanel("Rounded walnut upper frame",panel,Vector3.zero,V(width,.13f,depth),.17f,deskWood,.027f);
  PrecisionPanel("Shadow rebate beneath face",panel,V(0,.067f,0),V(4.57f,.024f,3.22f),.12f,deskRubber);
  PrecisionPanel("Fine brass outer inlay",panel,V(0,.082f,0),V(4.49f,.018f,3.14f),.10f,deskGold,.004f);
  PrecisionPanel("Black enamel face insert",panel,V(0,.093f,0),V(4.46f,.018f,3.11f),.09f,deskBlack,.004f);
  // Deliberate panel separation and fitted screw positions, as in the selected reference.
  foreach(float z in new[]{-.94f,.57f,1.48f})foreach(float x in new[]{-2.10f,2.10f})InstrumentScrew(panel,V(x,.105f,z),Vector3.up,.034f);
  Box("Horizontal brass panel rule",panel,V(0,.106f,.59f),V(4.17f,.008f,.009f),deskGold,.001f);
  return panel;
 }
 static void ArcSolid(string name,Transform p,Vector3 at,float xWidth,float inner,float outer,float from,float to,Material material,int segments=56){
  var vs=new List<Vector3>();var ns=new List<Vector3>();var uv=new List<Vector2>();var ts=new List<int>();
  Action<Vector3,Vector3,Vector3,Vector3,Vector3> quad=(a,b,c,d,normal)=>{int k=vs.Count;if(Vector3.Dot(Vector3.Cross(b-a,c-a),normal)<0){var s=b;b=d;d=s;}vs.AddRange(new[]{a,b,c,d});for(int j=0;j<4;j++)ns.Add(normal);uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});ts.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});};
  for(int i=0;i<segments;i++){float a=Mathf.Lerp(from,to,i/(float)segments)*Mathf.Deg2Rad,b=Mathf.Lerp(from,to,(i+1f)/segments)*Mathf.Deg2Rad;Vector3 ra=V(0,Mathf.Cos(a),Mathf.Sin(a)),rb=V(0,Mathf.Cos(b),Mathf.Sin(b));for(int side=-1;side<=1;side+=2){var x=Vector3.right*(side*xWidth/2);quad(x+ra*inner,x+ra*outer,x+rb*outer,x+rb*inner,Vector3.right*side);}quad(V(-xWidth/2,0,0)+ra*outer,V(xWidth/2,0,0)+ra*outer,V(xWidth/2,0,0)+rb*outer,V(-xWidth/2,0,0)+rb*outer,(ra+rb).normalized);if(inner>.0001f)quad(V(-xWidth/2,0,0)+ra*inner,V(xWidth/2,0,0)+ra*inner,V(xWidth/2,0,0)+rb*inner,V(-xWidth/2,0,0)+rb*inner,-(ra+rb).normalized);if(i==0)quad(V(-xWidth/2,0,0)+ra*inner,V(xWidth/2,0,0)+ra*inner,V(xWidth/2,0,0)+ra*outer,V(-xWidth/2,0,0)+ra*outer,V(0,Mathf.Sin(a),-Mathf.Cos(a)));if(i==segments-1)quad(V(-xWidth/2,0,0)+rb*inner,V(xWidth/2,0,0)+rb*inner,V(xWidth/2,0,0)+rb*outer,V(-xWidth/2,0,0)+rb*outer,V(0,-Mathf.Sin(b),Mathf.Cos(b)));}
  for(int i=0;i<vs.Count;i++){var radial=V(0,vs[i].y,vs[i].z).normalized;float alignment=Vector3.Dot(ns[i],radial);if(Mathf.Abs(ns[i].x)<.01f&&Mathf.Abs(alignment)>.98f)ns[i]=radial*Mathf.Sign(alignment);}
  var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetNormals(ns);mesh.SetUVs(0,uv);mesh.SetTriangles(ts,0);MeshObject(name,p,SaveMesh(mesh,"Sector_"+meshSerial++),material,at);
 }
