 static Transform PrecisionGauge(Transform parent,Vector3 at,string unit,float radius){
  var g=Group("Precision "+unit+" instrument",parent,at);float r=radius;
  var housing=Lathe("Stepped turned gauge bezel",g,Vector3.zero,new[]{new Vector2(0,-.045f),new Vector2(r*1.08f,-.045f),new Vector2(r*1.10f,-.025f),new Vector2(r*1.10f,.010f),new Vector2(r*1.06f,.028f),new Vector2(r*1.03f,.044f),new Vector2(r*.99f,.048f),new Vector2(r*.96f,.035f),new Vector2(r*.96f,.010f),new Vector2(0,.010f)},deskGold,96);housing.transform.localRotation=Quaternion.Euler(90,0,0);
  Cylinder("Cream calibrated gauge face",g,V(0,0,.018f),V(0,0,.022f),r*.95f,deskIvory,96);
  var ring=new List<Vector3>();for(int i=0;i<=96;i++){float a=i*2*Mathf.PI/96;ring.Add(V(Mathf.Cos(a)*r*.91f,Mathf.Sin(a)*r*.91f,.025f));}Tube("Printed fine outer circle",g,ring.ToArray(),.0016f,deskDarkGold,6);
  for(int i=0;i<=60;i++){float a=(-130+i*260f/60)*Mathf.Deg2Rad;float length=i%6==0?r*.13f:i%3==0?r*.09f:r*.055f;var tick=Box("Calibrated fine graduation",g,V(-Mathf.Sin(a)*(r*.84f-length*.5f),Mathf.Cos(a)*(r*.84f-length*.5f),.027f),V(i%6==0?.006f:.0035f,length,.002f),deskRubber,.0005f);tick.transform.localRotation=Quaternion.Euler(0,0,a*Mathf.Rad2Deg);}
  for(int i=0;i<=10;i++){float a=(-130+i*26)*Mathf.Deg2Rad;Label(g,(i*(unit=="km/h"?2:1)).ToString(),V(-Mathf.Sin(a)*r*.62f,Mathf.Cos(a)*r*.62f,.031f),.40f,C("312B21"));}
  if(unit=="bar"){var range=new List<Vector3>();for(int i=0;i<=16;i++){float a=(96+i*34f/16)*Mathf.Deg2Rad;range.Add(V(-Mathf.Sin(a)*r*.87f,Mathf.Cos(a)*r*.87f,.029f));}Tube("Red pressure limit band",g,range.ToArray(),.009f,red,8);}
