 static void PrecisionBackboard(Transform deck){
  var back=Group("Stepped walnut instrument backboard",deck,V(0,.65f,-1.27f));back.localRotation=Quaternion.Euler(-15,0,0);
  // Slightly taller two-dial section and a rounded shoulder down to the readout.
  Vector2[] outline={new Vector2(-2.20f,-.55f),new Vector2(2.20f,-.55f),new Vector2(2.20f,.52f),new Vector2(-.45f,.52f),new Vector2(-.78f,.36f),new Vector2(-2.20f,.36f)};
  // User-facing coordinates are mirrored, so the tall dial section is on local +x.
  var smooth=new List<Vector2>();for(int i=0;i<outline.Length;i++){var prev=outline[(i+outline.Length-1)%outline.Length];var p=outline[i];var next=outline[(i+1)%outline.Length];float trim=.085f;var a=p+(prev-p).normalized*trim;var b=p+(next-p).normalized*trim;for(int j=0;j<=8;j++){float q=j/8f;smooth.Add((1-q)*(1-q)*a+2*(1-q)*q*p+q*q*b);}}
  var shell=ProfileSolid("Contoured walnut instrument surround",back,Vector3.zero,smooth.ToArray(),.18f,deskWood,.020f);shell.transform.localRotation=Quaternion.Euler(-90,0,0);
  foreach(var row in new[]{new{scale=.967f,z=.102f,mat=deskGold},new{scale=.959f,z=.116f,mat=deskBlack}}){var shape=smooth.Select(p=>p*row.scale).ToArray();var panel=ProfileSolid("Fitted backboard inlay",back,V(0,0,row.z),shape,.016f,row.mat,.003f);panel.transform.localRotation=Quaternion.Euler(-90,0,0);}
  experience.pressureNeedle=PrecisionGauge(back,U(-1.33f,-.005f,.139f),"bar",.405f);experience.speedNeedle=PrecisionGauge(back,U(-.13f,-.005f,.139f),"km/h",.405f);
  // The status screen is an actual inset in the panel, never a floating black rectangle behind it.
  var display=Group("Recessed speed pressure status display",back,U(1.26f,-.065f,.139f));var rim=PrecisionPanel("Readout brass bezel",display,Vector3.zero,V(1.23f,.025f,.68f),.045f,deskGold,.004f);rim.transform.localRotation=Quaternion.Euler(90,0,0);var glassFace=PrecisionPanel("Readout dark glass",display,V(0,0,.015f),V(1.20f,.016f,.65f),.040f,deskRubber,.003f);glassFace.transform.localRotation=Quaternion.Euler(90,0,0);experience.statusDock=Group("Embedded status canvas anchor",display,V(0,0,.026f));experience.statusDock.localRotation=Quaternion.Euler(0,180,0);
  foreach(float x in new[]{-2.06f,2.06f})InstrumentScrew(back,V(x,x>0?.36f:.20f,.14f),Vector3.forward,.032f);
 }
 static void MergeConsoleStatic(Transform deck){
  Func<Transform,bool> animated=t=>{for(;t&&t!=deck;t=t.parent)if(t.name.StartsWith("Moving ")||t.GetComponent<AtelierControl>()||t.GetComponent<TMP_Text>())return true;return false;};
  var groups=deck.GetComponentsInChildren<MeshRenderer>().Where(r=>r.sharedMaterial&&r.sharedMaterials.Length==1&&r.sharedMaterial.renderQueue<2500&&r.GetComponent<MeshFilter>()&&!animated(r.transform)).GroupBy(r=>r.sharedMaterial).ToArray();
  foreach(var group in groups){var list=group.ToArray();if(list.Length<3)continue;var combined=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};combined.CombineMeshes(list.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=deck.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray());MeshObject("Console static finish "+group.Key.name,deck,SaveMesh(combined,"ConsoleCombined_"+meshSerial++),group.Key);foreach(var r in list){UnityEngine.Object.DestroyImmediate(r.GetComponent<MeshFilter>());UnityEngine.Object.DestroyImmediate(r);}}
  var renderers=deck.GetComponentsInChildren<MeshRenderer>();long triangles=renderers.Where(r=>r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).Sum(r=>(long)r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);File.WriteAllText(AtelierEditor.Root+"/Reports/precision-console-metrics.txt",triangles+" modeled triangles\n"+renderers.Length+" mesh renderers including moving mechanisms and text\nStatic panels, graduations and fasteners batched by finish; moving mechanisms stay separate.\n");
 }
